Lemma ticks_ok_hdr_st st pf : ticks_ok st -> ticks_ok (hdr_st st pf).
Proof.
ltac2:(KReplay.run1 (kr_t_F_free_K ()) ["CANSEC1"] "h02pfh12sth22TKp;1p;2p;3p;4g00@?j15Tg00AYj12Tg02`_j16Tg01DZj21Tg010;j10Tg00B>j14Tg00EOj37Tg02a=j29Tg02a]j43Tg02^1j28Tg00QMR0g002UR1f1R2#5g00RdR3#2R4#6,12R5g00RFR6%03R7#6,12R8%07#0#0#0#0#0#4R7f2R937R:37%43,15%24#2#4,96P:P5P6P9P8P7f0R7C3C3C31892#5eW2X01X10P2P7O2W0W1o"). Qed.

Lemma hdr_st_cell_read st pf rid o : ticks_ok st ->
  cell_read (get_shadow (hdr_st st pf) rid) o =
    if (N.eqb rid (fst pf) && ((o =? snd pf - 1) || (o =? snd pf - 2) || (o =? snd pf - 3)))%bool
    then Known (if o =? snd pf - 3 then 255 else 0)
